old=build_reference('schema',2,'Thing')
new=build_reference('schema',3,'Thing')
print('versioned_refs',old,new)
assert old=={'$ref':'#/definitions/Thing'}
assert new=={'$ref':'#/components/schemas/Thing'}

from marshmallow import fields
from apispec.ext.marshmallow.common import filter_excluded_fields
class Meta:
 exclude=['hidden']
 dump_only=['meta_output']
values={'visible':fields.String(),'hidden':fields.String(),'output':fields.String(dump_only=True),'meta_output':fields.String()}
all_fields=filter_excluded_fields(values,Meta,exclude_dump_only=False)
input_fields=filter_excluded_fields(values,Meta,exclude_dump_only=True)
print('filtered_field_names',list(all_fields),list(input_fields))
assert set(all_fields)=={'visible','output','meta_output'}
assert set(input_fields)=={'visible'}

from prettytable import from_html_one
html='<table><tr><td>x</td></tr></table><table><tr><td>y</td></tr></table>'
try:
 from_html_one(html)
except ValueError as exc:
 print('single_table_rejection',str(exc));assert 'More than one' in str(exc)
else:
 raise AssertionError('multiple HTML tables silently accepted')

from bottle import Router,HTTPError
r=Router();r.add('/item/<id:int>','GET','target');value=r.match({'PATH_INFO':'/item/42','REQUEST_METHOD':'GET'});print('dynamic_rule_position',value)
assert value==('target',{'id':42})
try:
 r.match({'PATH_INFO':'/missing','REQUEST_METHOD':'GET'})
except HTTPError as exc:
 assert exc.status_code==404
else:
 raise AssertionError('missing route accepted')

import tomli
from decimal import Decimal
value=tomli.loads('x=1.25',parse_float=Decimal)['x'];print('scalar_callback_value',value,type(value).__name__)
assert isinstance(value,Decimal) and value==Decimal('1.25')
try:
 tomli.loads('x=1.25',parse_float=lambda s:[float(s)])
except ValueError:
 print('structural_callback_rejected',True)
else:
 raise AssertionError('list callback result accepted')

import tomli
doc='text = "'+chr(92)+'q"'
try:
 tomli.loads(doc)
except tomli.TOMLDecodeError as exc:
 print('unknown_escape_rejected',str(exc))
else:
 raise AssertionError('unknown escape silently erased')

import tomli
value=tomli.loads("text='hello'\nnext=2");print('literal_terminator_position',value)
assert value=={'text':'hello','next':2}

import tomli
value=tomli.loads('first=1\r\nsecond=2\r\n');print('normalized_document_lines',value)
assert value=={'first':1,'second':2}

import tomli
doc='[[items]]\n[items.meta]\nv=1\n[[items]]\n[items.meta]\nv=2\n';value=tomli.loads(doc);print('fresh_array_namespaces',value)
assert value=={'items':[{'meta':{'v':1}},{'meta':{'v':2}}]}
try:
 tomli.loads('value=42\n[[value]]')
except tomli.TOMLDecodeError:
 print('array_scalar_collision_rejected',True)
else:
 raise AssertionError('scalar overwritten by array table')

from tinydb import TinyDB
from tinydb.table import Document
from tinydb.storages import MemoryStorage
db=TinyDB(storage=MemoryStorage);t=db.table('records');value=t.insert(Document({'v':'old'},doc_id=5));print('inserted_identity',value);assert value==5
try:
 t.insert(Document({'v':'new'},doc_id=5))
except ValueError:
 assert t.get(doc_id=5)=={'v':'old'}
else:
 raise AssertionError('duplicate identity overwrote existing document')

from tinydb import TinyDB,where
from tinydb.table import Document
from tinydb.storages import MemoryStorage
db=TinyDB(storage=MemoryStorage);t=db.table('records');t.insert({'name':'old'});value=t.upsert({'name':'new'},where('name')=='new');print('upsert_insert_transition',value,t.all())
assert value==[2] and t.get(doc_id=2)=={'name':'new'}
value=t.upsert(Document({'name':'explicit'},doc_id=7));assert value==[7] and t.get(doc_id=7)=={'name':'explicit'}

from tinydb import TinyDB,where
from tinydb.storages import MemoryStorage
db=TinyDB(storage=MemoryStorage);t=db.table('records');ids=t.insert_multiple([{'n':1},{'n':2},{'n':3}]);removed=t.remove(where('n')==2);print('removed_subset',removed,t.all())
assert removed==[ids[1]] and t.all()==[{'n':1},{'n':3}]
try:
 t.remove(doc_ids=[999])
except KeyError:
 print('absent_id_rejected',True)
else:
 raise AssertionError('absent ID silently ignored')

from tinydb.utils import LRUCache
c=LRUCache(3);payload=['value'];c['key']=payload;value=c['key'];print('cache_value_channel',value);assert value is payload
try:
 c['missing']
except KeyError:
 print('missing_cache_key_rejected',True)
else:
 raise AssertionError('missing key returned a value')

